"""English text for Chinese-authored lessons; musical data and answer indices are shared."""

from practising_piano_easily.trainers.beginner_course import LESSONS, PIECES
from practising_piano_easily.tutorial import load_lessons


COURSES = {
    "find_c": ("01 Find middle C: your first treble-staff note", "Find C immediately to the left of a group of two black keys. Middle C is C4 (MIDI 60) in this app.\nThe bottom line of the treble staff is E4; middle C sits on a short ledger line below it.\nPlay C4, D4, E4, C4. Each open notehead without a stem is a whole note lasting four beats.\nThere is no time limit. After matching the notes, release the keys to continue."),
    "right_five": ("02 Right-hand five-finger position: C D E F G", "Place your right thumb on C4, then fingers 2, 3, 4 and 5 on D4, E4, F4 and G4. Keep your hand relaxed.\nAdjacent notes move between a line and a space on the staff. A filled notehead with a stem is a quarter note: one beat.\nIn 4/4, each bar has four quarter-note beats. Count slowly; speed is not graded."),
    "left_bass": ("03 Left-hand reading: low C and A", "The lower staff uses bass clef: its bottom line is G2 and top line is A3. Find C3 and A2 first.\nOnly the left hand plays here. An open notehead with a stem is a half note: two beats.\nPlay C3, G3, A2, E3 twice. Match the written octave: C4 does not replace C3."),
    "c_chord": ("04 Your first chord: C E G", "A C major triad contains C, E and G. Play C4, E4 and G4 with the right hand; fingers 1, 3 and 5 are one possible starting point.\nVertically aligned notes sound together. You may add them one at a time; the app waits for the full target.\nRelease extra red notes while keeping correct ones. Once correct, release the chord to continue."),
    "am_chord": ("05 A minor triad: A C E", "Am contains A, C and E. Play A3, C4 and E4 with the right hand. A3 is below middle C.\nLow notes require ledger lines below the treble staff. Use the keyboard labels while learning these positions.\nListen to C and Am, then practice slowly. Accuracy and a relaxed hand matter more than speed."),
    "two_hands": ("06 Both hands: four bars of C and Am", "This original four-bar exercise alternates C and Am. The right hand plays chords; the left plays C3 or A2.\nNotes aligned vertically across both staves belong to the same group.\nYou may place the left hand first, then add the right. Count four beats yourself before releasing and moving on."),
    "white_key_walk": ("07 White-Key Path: an original four-bar tune", "This right-hand tune uses the white keys of C major. Read one bar, then connect the bars.\nAs notes rise on the staff, the keys usually move to the right. Release and press again for repeated notes.\nYou can hide or restore note-name hints whenever you like. Practice at your own pace."),
    "left_five": ("08 Left-hand five-finger position: reading up from C3", "Place left-hand fingers 5, 4, 3, 2 and 1 on C3, D3, E3, F3 and G3.\nUse C3 and G3 as bass-staff landmarks. Do not shift this exercise to C4.\nAscending moves from little finger to thumb; descending reverses it. Keep the wrist natural."),
    "read_thirds": ("09 Steps and skips: seconds and thirds", "C to D is a second and moves from a line to a space. C to E is a third and skips one staff position.\nCompare neighboring notes with C E G. Read the distance as well as the letter names.\nRepeated notes need a fresh press. Note-name hints are optional."),
    "long_short": ("10 One, two and four beats: note values", "A quarter note lasts one beat, a half note two, and a whole note four. Listen first, then count aloud.\nA longer note does not mean pressing the same key repeatedly. Repeated written notes do need separate attacks.\nThis mode checks pitch, not timing or how long you hold a key."),
    "eighth_dotted": ("11 Half-beats and dots: eighth notes", "An eighth note with one flag lasts half a beat. A dotted quarter lasts one and a half beats.\nThe first bar has eight eighth notes: four beats in total. Listen for the long-short combinations in the next bar.\nFind the notes slowly. Learn the rhythm by listening and counting; the app does not grade rhythm."),
    "f_chord": ("12 F major: F A C", "F major contains F, A and C. Play F3 A3 C4 with the right hand; fingers 1, 3 and 5 are one option.\nThe second half adds left-hand F2. The two Fs are in different octaves.\nPractice hands separately if needed. Do not force a stretch."),
    "g_chord": ("13 G major: G B D", "G major contains G, B and D. Play G3 B3 D4. B3 is the white key immediately below C4.\nNotice how the stacked thirds appear on the staff.\nLater, add G2 in the left hand. Skipping white keys does not produce a major chord on every root: check the intervals."),
    "dm_chord": ("14 D minor: D F A", "Dm contains D, F and A. Play D4 F4 A4. D to F is a minor third; F to A is a major third.\nCompare its sound with C and Am. A mood word alone does not define a chord.\nCheck each note, then combine them. Add D3 in the left hand in the second half."),
    "em_chord": ("15 E minor: E G B", "Em contains E, G and B. Play E4 G4 B4; B4 is just below C5.\nE to G is a minor third and G to B a major third. Minor chords can use only white keys.\nAdd E3 in the left hand later, and check both staff positions."),
    "primary_cadence": ("16 C F G C: your first chord progression", "In C major, C, F and G are I, IV and V. Listen to the sense of return when C comes back.\nRepeat the four-bar pattern twice. Look ahead to the next root before moving.\nRelease the keys between groups. You may build each new chord slowly."),
    "c_first_inversion": ("17 C in first inversion: E G C", "Move the lowest C of C E G up an octave to get E G C. The chord is still C major.\nAlternate C4 E4 G4 with E4 G4 C5 and listen to the change of bass.\nScore practice requires the written octaves. The separate chord trainer also offers any-inversion practice."),
    "c_second_inversion": ("18 C in second inversion: G C E", "Second inversion has G as the lowest note. Here, play G3 C4 E4.\nCompare root position C4 E4 G4, first inversion E4 G4 C5, and second inversion G3 C4 E4.\nDistinguish the chord root from its current lowest note. All three contain C, E and G."),
    "common_tones": ("19 C to Am: connecting with a small move", "C contains C E G; Am contains A C E. C and E are common tones. Use C4 E4 A4 for Am.\nOnly one pitch changes from C4 E4 G4, keeping the hand positions close.\nThis beginner mode still asks you to release each correct group. It does not assess legato or sustained common tones."),
    "broken_c": ("20 Broken chords: C E G one note at a time", "Playing notes together makes a block chord; playing them in sequence makes a broken chord. Find C4 E4 G4 first.\nPlay C E G E with one beat per note. Later, reach C5 and return to middle C.\nMove the hand to reach C5 instead of forcing your fingers apart."),
    "broken_am": ("21 Broken chords: a conversation between Am and C", "Play A3 C4 E4 in sequence, then move to C4 E4 G4. Notice their shared tones.\nTreat two bars as a phrase and listen to ascending and descending shapes.\nFingering is a suggestion. The app checks pitches and octaves, not which fingers you use."),
    "left_broken": ("22 Left-hand accompaniment: roots and fifths", "Play C3 to G3, A2 to E3, F2 to C3, and G2 to D3 with the left hand: the root and fifth of each chord.\nEach note lasts two beats. Move the forearm with changes of register instead of twisting only the wrist.\nListen to the harmonic direction in the bass before returning to both-hand pieces."),
    "dominant_seventh": ("23 G7 to C: hearing a resolution", "G7 contains G B D F. Compared with G, it adds F. Play B3 D4 F4 in the right hand and G2 in the left.\nListen to B3 moving to C4 and F4 moving to E4 when the harmony returns to C.\nThe right hand omits G, but both hands together contain all four chord tones."),
    "soft_sevenths": ("24 Cmaj7 and Am7: seventh chords", "Cmaj7 contains C E G B; Am7 contains A C E G. Each adds another third above a triad.\nPlay E4 G4 B4 over left-hand C3, then C4 E4 G4 over A2. Splitting the notes avoids a wide one-hand stretch.\nCompare them twice, then choose a practice piece. Speed and retests are not advancement requirements."),
    "song_twinkle": ("S01 Twinkle, Twinkle: a one-hand melody", "A beginner C-major arrangement of the traditional melody Ah! vous dirai-je, maman: twelve bars without lyrics.\nPractice four bars at a time, noticing the contrasting middle and returning ending. Move the hand for G to A.\nQuarter notes last one beat and half notes two. Use the score navigation controls to look ahead."),
    "song_mary": ("S02 Mary Had a Little Lamb: a five-finger tune", "A beginner C-major arrangement of a traditional nursery melody, without lyrics, using C4 to G4.\nRelease and press again when E or D repeats. A half note means two beats, not two presses.\nListen to how the first and second phrases end differently."),
    "song_frere": ("S03 Frere Jacques: introducing eighth notes", "A C-major arrangement of the traditional French round. This score plays only one melody, not the full round.\nIn bars 5 and 6, G A G F are four eighth notes lasting two beats; E and C then last one beat each.\nThe ending C4 G3 C4 moves the right hand left. Check the octave."),
    "song_ode": ("S04 Ode to Joy: the theme, not the whole symphony", "A sixteen-bar, one-hand beginner arrangement of the theme from Beethoven's Ninth Symphony in C major.\nRearticulate repeated notes. In bar 4, dotted-quarter E lasts one and a half beats, followed by half-beat D.\nA contrasting phrase begins at bar 9. Practice four bars at a time before connecting them."),
    "song_morning": ("S05 Morning Light: an original five-finger piece", "An original eight-bar right-hand exercise using C4 D4 E4 F4 G4, with steps and thirds.\nEach four-bar group is a phrase. The second phrase has a similar shape but a different ending.\nStart with relaxed movement, correct notes, and clear releases."),
    "song_steps": ("S06 Stairway: an original ascending and descending tune", "An eight-bar right-hand exercise that rises to C5 and descends along the white keys.\nThis is not a fixed five-finger position. Move the hand instead of stretching.\nCompare stepwise movement through lines and spaces with the leap from G4 to C5."),
    "song_echo": ("S07 Echo: an original dialogue between the hands", "In this eight-bar exercise, the right hand asks a question and the left answers an octave lower. They do not play together.\nRelax the resting hand. Check whether the current phrase is on the upper or lower staff.\nConnect treble- and bass-staff reading by alternating similar shapes between the hands."),
    "song_am_river": ("S08 Minor River: an original A-minor tune", "Eight bars built mainly from A C E and D F A. All notes use white keys, but A is the tonal center.\nThe right hand begins on A3. Notice ledger lines below middle C and the movement toward A4.\nListen to whether the final A3 feels different from the endings of the C-major exercises."),
    "song_bass_path": ("S09 Bass Walk: an original left-hand melody", "An eight-bar bass-staff reading exercise. The right hand rests.\nC4 appears on a ledger line above the bass staff: it is the same middle C as in lesson 1.\nThe second half moves lower. Check the octave as well as the note name."),
    "song_four_homes": ("S10 Four Windows: original chords for both hands", "Eight bars for both hands: C Am F G, followed by C Dm G7 C.\nThe right hand uses nearby inversions and the left plays roots. Read each staff separately before combining groups.\nTry counting four beats before releasing each chord. Hold duration is not graded."),
    "song_lantern": ("S11 Lantern: original two-beat chord changes", "Eight bars with two both-hand chords per bar. The left hand plays bass notes; the right uses compact two- and three-note shapes.\nRead bass moves such as C3 to G3 before adding the right hand. Add notes slowly if needed.\nThis is block-chord coordination, not an independent melody over a sustained bass. Release all keys after each correct group."),
    "song_evening": ("S12 Evening Breeze: original seventh-chord practice", "Twelve bars for both hands using nearby voicings of Cmaj7 Am7 Dm7 G7.\nFour chord tones are shared between the hands, so the right hand need not stretch across a seventh.\nRecommended after lesson 24. Hints and corrections are welcome."),
}

# Display-only translations, in the same order as tutorial._ACTIVITIES.
QUIZZES = (
    ("What is useful when learning C major for the first time?", ("Memorize only the hand shape", "Say C E G, find the keys, play and listen", "Immediately practice every advanced chord"), "Connect the symbol, note names, keyboard positions and sound. Marking a chapter as read does not prove mastery."),
    ("Which note is one semitone above E?", ("F", "F#", "G"), "E and F are adjacent keys with no black key between them. B and C are also a semitone apart."),
    ("How should the fourth note of F major be spelled?", ("A#", "Bb", "B"), "F G A Bb C D E uses every letter once. A# and Bb share a key, but Bb is the correct scale spelling here."),
    ("What is the correctly spelled major third above F#?", ("A", "A#", "Bb"), "Count letters F G A, then measure four semitones from F#: the answer is A#, not its enharmonic equivalent Bb."),
    ("C-D# and C-Eb use the same keys. Do they have the same interval name?", ("Yes, both are minor thirds", "No: an augmented second and a minor third"), "Interval names depend on both letter distance and semitone distance, not just the number of keys."),
    ("Which note changes when C major becomes C minor?", ("C becomes B", "E becomes Eb", "G becomes Gb"), "C E G becomes C Eb G. Lower the third by a semitone; keep the root and fifth."),
    ("Which notes form a D major triad?", ("D F A", "D F# A", "D G A"), "A major third above D is F#, and a perfect fifth is A. Skipping white keys does not work on every root."),
    ("Left hand C3, right hand E4 G4 C5: which position is the complete chord in?", ("Root position", "First inversion", "Second inversion"), "Look at the lowest note across both hands. C is lowest, so the complete chord is in root position."),
    ("Is C/D necessarily an inversion of the C triad?", ("Yes, every slash chord is an inversion", "No, D is not a tone of the C triad"), "A slash specifies the bass. An inversion requires that bass to be one of the chord tones."),
    ("What differs between Cmaj7 and C7?", ("The third: E or Eb", "The seventh: B or Bb", "The root: C or B"), "Both begin with C E G. Cmaj7 adds B; C7 adds Bb."),
    ("What results from lowering the fifth of Cm7 by one semitone?", ("Cm7b5", "Cdim7", "Cmaj7"), "C Eb G Bb becomes C Eb Gb Bb. Cdim7 would also lower Bb to Bbb."),
    ("What is iii7 in F major?", ("Am7", "A7", "Abmaj7"), "Start on A, the third degree of F G A Bb C D E, and take alternate scale notes: A C E G."),
    ("In C major, what is a common tonic target of G7?", ("Return to C", "It must go to Am", "It cannot return to C"), "B often moves to C and F to E in a V7-I resolution. Actual music can choose other continuations."),
    ("Which raised note is important when Em becomes E7 in A minor?", ("G becomes G#", "B becomes C", "E becomes F"), "G# is the leading tone a semitone below A. E7 also adds D. Natural-minor G is not itself a mistake."),
    ("What is a common interpretation of A7 in C-A7-Dm-G7?", ("The diatonic vi chord of C major", "The secondary dominant of Dm: V7/ii", "The whole piece has certainly modulated to A major"), "A7 contains chromatic C# and often leads to Dm. One chromatic chord alone does not prove a modulation."),
    ("What is the key difference between Cadd9 and C9?", ("C9 also contains the minor seventh Bb", "Cadd9 has no third E", "They are identical"), "Add9 adds a ninth to a triad. C9 adds a ninth to a dominant-seventh structure."),
    ("Must a practical C13 voicing sound all seven theoretical tones at once?", ("Yes, any omission makes it a different chord", "No, a voicing may omit selected tones"), "Distinguish the theoretical collection from a practical voicing. E, Bb and A often matter; choose other notes according to register, bass and instrumentation."),
    ("Does a smaller total voice-leading distance always sound better?", ("Yes, it is the only criterion", "No, melody, rhythm and expressive intent also matter"), "Movement is an objective comparison, not an artistic quality score."),
    ("What helps after repeated mistakes on the same exercise?", ("Play faster without checking", "Name the root, third and fifth, locate the mismatch and play slowly", "Skip to a harder level"), "Identify whether the difficulty is finding keys, constructing the chord or choosing the bass. Build accuracy before speed."),
)

EN = {"Tutorial content: Simplified Chinese · Read, listen, play, then test yourself.":
      "English chord course · Read, listen, play, then test yourself.",
      "Beginner course & sheet music": "Beginner lessons / scores"}
for lesson in LESSONS + PIECES:
    title, instructions = COURSES[lesson.id]
    EN[lesson.title] = title
    EN[lesson.instructions] = instructions
for original, translated in zip(load_lessons(), load_lessons("en"), strict=True):
    EN[original.title] = translated.title
questions = (quiz for lesson in load_lessons() for quiz in lesson.quizzes)
for original, (question, options, explanation) in zip(questions, QUIZZES, strict=True):
    EN[original.question] = question
    EN[original.explanation] = explanation
    for source, target in zip(original.options, options, strict=True):
        if source != target:
            EN[source] = target
